{
  "steps": [
    {
      "type": "launch_app",
      "name": "启动应用"
    },
    {
      "type": "input",
      "name": "输入账号",
      "locator_type": "id",
      "locator_value": "username"
    },
    {
      "type": "input",
      "name": "输入密码",
      "locator_type": "id",
      "locator_value": "password"
    },
    {
      "type": "click",
      "name": "点击登录",
      "locator_type": "id",
      "locator_value": "login_btn"
    }
  ]
}

{
  "steps": [
    {
      "type": "shell",
      "name": "清理应用缓存",
      "command": "pm clear ${app_package}"
    },
    {
      "type": "launch_app",
      "name": "重新启动应用"
    }
  ]
}

{
  "steps": [
    {
      "type": "launch_app",
      "name": "启动应用"
    },
    {
      "type": "click",
      "name": "同意隐私协议",
      "locator_type": "text",
      "locator_value": "同意",
      "optional": true
    },
    {
      "type": "wait",
      "name": "等待首页加载",
      "timeout": 5000
    }
  ]
}
